import { BASE_CLASS_PREFIX } from '../base/constants';

const cssClasses = {
    PREFIX: `${BASE_CLASS_PREFIX}-tag`,
};

const strings = {
    TAG_SIZE: ['default', 'small', 'large'],
    TAG_COLOR: [
        'grey',
        'red',
        'pink',
        'purple',
        'violet',
        'indigo',
        'blue',
        'light-blue',
        'cyan',
        'teal',
        'green',
        'light-green',
        'lime',
        'yellow',
        'amber',
        'orange',
        'white',
    ],
    TAG_TYPE: ['light', 'solid', 'ghost'],
    AVATAR_SHAPE: ['square', 'circle'],
};

export { cssClasses, strings };

@mixin tag-style($color, $type) {
    @if $type==solid {
        background-color: unquote("rgba(var(--semi-#{$color}-5), 1)");
        color: rgba(var(--semi-white), 1);
    }

    @else if $type==ghost {
        background-color: transparent;
        border: 1px solid unquote("rgba(var(--semi-#{$color}-4), 1)");
        color: unquote("rgba(var(--semi-#{$color}-5), 1)");
    }

    @else if $type==light {
        background-color: unquote("rgba(var(--semi-#{$color}-5), 0.15)");
        color: unquote("rgba(var(--semi-#{$color}-8), 1)");
    }

    @else {
        @error "Unknown type #{$type}.";
    }
}

$module: #{$prefix}-tag;
$tag-small: 20px;
$tag-large: 24px;

$tag-margin-bottom: $spacing-tight;
$tag-margin-right: $spacing-tight;

.#{$prefix}-rtl,
.#{$prefix}-portal-rtl {
    .#{$module} {
        direction: rtl;

        &-close {
            padding-left: auto;
            padding-right: $spacing-tag_close-paddingLeft;
        }

        &-closable {
            padding: $spacing-tag_closable-paddingTop $spacing-tag_closable-paddingLeft $spacing-tag_closable-paddingBottom $spacing-tag_closable-paddingRight;
        }

        &-avatar-square,
        &-avatar-circle {
            .#{$prefix}-avatar {
                margin-right: auto;
                margin-left: $spacing-tag_avatar-marginRight;
            }
        }

        &-avatar-square {
            padding-right: auto;
            padding-left: $spacing-tag_avatar_square-paddingRight;
        }

        &-avatar-circle {
            padding: $spacing-tag_avatar_circle-paddingTop $spacing-tag_avatar_circle-paddingLeft $spacing-tag_avatar_circle-paddingBottom $spacing-tag_avatar_circle-paddingRight;
        }
    }

    .#{$module}-group {
        direction: rtl;

        .#{$module} {
            margin-right: auto;
            margin-left: $spacing-tag_group-marginRight;
        }
    }

    .#{$module}-rest-group-popover {
        direction: rtl;

        .#{$module} {
            margin-right: 0;
            margin-left: $spacing-tag_group-marginRight;
            &:last-of-type {
                margin-right: auto;
                margin-left: 0;
            }
        }
    }
}

